import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

import { Car, Manufacturer, ManufacturerRating, Rating } from './models';

/** Paths from gwt/.../shared/api/ApiPaths.java, served under /api (same origin). */
const API_ROOT = '/api';
const MANUFACTURERS = `${API_ROOT}/manufacturers`;
const RATINGS = `${API_ROOT}/ratings`;
const CARS = `${API_ROOT}/cars`;

/** LIMIT_ALL in CarsResource: returns every car. */
const LIMIT_ALL = -1;

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getManufacturers(): Observable<Manufacturer[]> {
    return this.http.get<Manufacturer[]>(MANUFACTURERS);
  }

  /** Creates the manufacturer when it has no id, updates it otherwise (ManufacturersResource.saveOrCreate). */
  saveManufacturer(manufacturer: Manufacturer): Observable<Manufacturer> {
    return this.http.post<Manufacturer>(MANUFACTURERS, manufacturer);
  }

  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`${MANUFACTURERS}/${id}`);
  }

  /** ManufacturersResource.getAverageRatings: @Path(ApiPaths.RATING) under /manufacturers. */
  getAverageRatings(): Observable<ManufacturerRating[]> {
    return this.http.get<ManufacturerRating[]>(`${MANUFACTURERS}/ratings`);
  }

  getRatings(): Observable<Rating[]> {
    return this.http.get<Rating[]>(RATINGS);
  }

  saveRating(rating: Rating): Observable<Rating> {
    return this.http.post<Rating>(RATINGS, rating);
  }

  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`${RATINGS}/${id}`);
  }

  getCars(): Observable<Car[]> {
    const params = new HttpParams().set('offset', 0).set('limit', LIMIT_ALL);
    return this.http.get<Car[]>(CARS, { params });
  }
}
