import { APP_BASE_HREF, HashLocationStrategy, PlatformLocation } from '@angular/common';
import { Inject, Injectable, Optional } from '@angular/core';

/**
 * Hash routing with the GWT history tokens: the screens live at `#manufacturer`, `#rating`
 * and `#report` (not `#/manufacturer`), so the e2e tests and the menubar hrefs match the GWT app.
 */
@Injectable()
export class TokenHashLocationStrategy extends HashLocationStrategy {
  constructor(platformLocation: PlatformLocation, @Optional() @Inject(APP_BASE_HREF) baseHref?: string) {
    super(platformLocation, baseHref);
  }

  override path(includeHash = false): string {
    return '/' + super.path(includeHash).replace(/^\/+/, '');
  }

  override prepareExternalUrl(internal: string): string {
    return '#' + internal.replace(/^\/+/, '');
  }
}
