import { ApplicationRef, Injectable, inject, signal } from '@angular/core';

export type MessageStyle = 'success' | 'error';

export interface AppMessage {
  id: number;
  text: string;
  style: MessageStyle;
}

/** Same default as MessageCloseDelay.DEFAULT in the GWT app. */
const CLOSE_DELAY_MS = 5000;

@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<AppMessage[]>([]);
  private nextId = 1;
  private readonly appRef = inject(ApplicationRef);

  /** Returns the id of the message so the caller can dismiss it again. */
  success(text: string): number {
    return this.add(text, 'success');
  }

  error(text: string): number {
    return this.add(text, 'error');
  }

  dismiss(id: number): void {
    this.messages.update((list) => list.filter((m) => m.id !== id));
  }

  private add(text: string, style: MessageStyle): number {
    const id = this.nextId++;
    this.messages.update((list) => [...list, { id, text, style }]);
    // Render now rather than on the next frame, so the message is in the DOM as soon as the action returns.
    this.appRef.tick();
    setTimeout(() => this.dismiss(id), CLOSE_DELAY_MS);
    return id;
  }
}
