import { ChangeDetectionStrategy, Component, OnInit, input, output } from '@angular/core';

import { Manufacturer } from '../core/models';

/** The "Manufacturer editor" popup (EditManufacturerView in GWT). It only collects the input. */
@Component({
  selector: 'app-edit-manufacturer',
  standalone: true,
  templateUrl: './edit-manufacturer.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EditManufacturerComponent implements OnInit {
  readonly manufacturer = input.required<Manufacturer>();
  readonly save = output<Manufacturer>();
  readonly closed = output<void>();

  /** Working copy; the list is only changed by the page. */
  draft: Manufacturer = { name: '' };

  ngOnInit(): void {
    this.draft = { ...this.manufacturer() };
  }

  onNameInput(event: Event): void {
    this.draft.name = (event.target as HTMLInputElement).value;
  }

  submit(): void {
    if (this.draft.name.trim() === '') {
      return;
    }
    this.save.emit({ ...this.draft, name: this.draft.name.trim() });
  }

  close(): void {
    this.closed.emit();
  }
}
