import { ApplicationRef, ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../core/api.service';
import { Manufacturer } from '../core/models';
import { MessageService } from '../core/message.service';
import { EditManufacturerComponent } from './edit-manufacturer.component';

@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [EditManufacturerComponent],
  templateUrl: './manufacturer.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ManufacturerComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);
  private readonly appRef = inject(ApplicationRef);

  readonly manufacturers = signal<Manufacturer[]>([]);
  /** The manufacturer shown in the editor popup: a new one, or a copy of the edited row. */
  readonly editing = signal<Manufacturer | null>(null);

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (list) => this.manufacturers.set(list),
      error: () => this.messages.error('The manufacturers could not be loaded.'),
    });
  }

  create(): void {
    this.editing.set({ name: '', cars: [] });
  }

  edit(manufacturer: Manufacturer): void {
    this.editing.set({ ...manufacturer });
  }

  closeEditor(): void {
    this.editing.set(null);
  }

  /**
   * Saves the manufacturer. The row and the success message are shown right away, as the
   * optimistic update the GWT table did not have: the server confirmation then replaces the
   * provisional row, and a rejected save rolls the row back and shows an error instead.
   */
  save(draft: Manufacturer): void {
    this.closeEditor();
    const previous = draft.id === undefined ? undefined : this.manufacturers().find((m) => m.id === draft.id);
    const provisional: Manufacturer = { ...draft };
    const successId = this.messages.success('The manufacturer has been saved.');
    this.manufacturers.update((list) =>
      previous ? list.map((m) => (m === previous ? provisional : m)) : [...list, provisional]);
    this.appRef.tick();

    this.api.saveManufacturer(draft).subscribe({
      next: (saved) => this.manufacturers.update((list) =>
        list.map((m) => (m === provisional ? saved : m))),
      error: () => {
        this.manufacturers.update((list) => previous
          ? list.map((m) => (m === provisional ? previous : m))
          : list.filter((m) => m !== provisional));
        this.messages.dismiss(successId);
        this.messages.error('The manufacturer could not be saved.');
      },
    });
  }

  delete(manufacturer: Manufacturer): void {
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    this.api.deleteManufacturer(manufacturer.id!).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((m) => m.id !== manufacturer.id)),
      error: () => this.messages.error('The manufacturer could not be deleted.'),
    });
  }
}
