import { ChangeDetectionStrategy, Component, OnInit, inject, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService } from '../core/api.service';
import { Car, Rating, carLabel } from '../core/models';
import { MessageService } from '../core/message.service';

@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './edit-rating.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EditRatingComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly saved = output<Rating>();
  readonly closed = output<void>();

  readonly cars = signal<Car[]>([]);
  readonly loadingCars = signal(true);
  readonly saving = signal(false);

  /** Car picked in the list; defaults to the first car, as the GWT form does. */
  selectedCar: Car | null = null;
  /** Rating entered by the user; null while the input is empty. */
  rating: number | null = null;

  protected readonly carLabel = carLabel;

  ngOnInit(): void {
    this.api.getCars().subscribe({
      next: (cars) => {
        this.cars.set(cars);
        this.selectedCar = cars[0] ?? null;
        this.loadingCars.set(false);
      },
      error: () => {
        this.loadingCars.set(false);
        this.messages.error('The cars could not be loaded.');
      },
    });
  }

  canSave(): boolean {
    return !this.saving() && !this.loadingCars() && this.selectedCar !== null && this.rating !== null;
  }

  save(): void {
    if (!this.selectedCar || this.rating === null) {
      return;
    }
    this.saving.set(true);
    this.api.saveRating({ rating: this.rating, car: this.selectedCar }).subscribe({
      next: (saved) => {
        this.messages.success('The rating has been saved.');
        this.saved.emit(saved);
      },
      error: () => {
        this.saving.set(false);
        this.messages.error('The rating could not be saved.');
      },
    });
  }

  close(): void {
    this.closed.emit();
  }
}
