import { ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../core/api.service';
import { Rating, carLabel } from '../core/models';
import { MessageService } from '../core/message.service';
import { EditRatingComponent } from './edit-rating.component';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [EditRatingComponent],
  templateUrl: './rating.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RatingComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly ratings = signal<Rating[]>([]);
  readonly editorOpen = signal(false);

  protected readonly carLabel = carLabel;

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (list) => this.ratings.set(list),
      error: () => this.messages.error('The ratings could not be loaded.'),
    });
  }

  create(): void {
    this.editorOpen.set(true);
  }

  closeEditor(): void {
    this.editorOpen.set(false);
  }

  onSaved(saved: Rating): void {
    this.ratings.update((list) => [...list, saved]);
    this.closeEditor();
  }

  delete(rating: Rating): void {
    if (!window.confirm(`Are you sure you want to delete ${carLabel(rating.car)}?`)) {
      return;
    }
    this.api.deleteRating(rating.id!).subscribe({
      next: () => this.ratings.update((list) => list.filter((r) => r.id !== rating.id)),
      error: () => this.messages.error('The rating could not be deleted.'),
    });
  }
}
