import { ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';
import { catchError, map } from 'rxjs';

import { ApiService } from '../core/api.service';
import { ManufacturerRating, Rating } from '../core/models';
import { MessageService } from '../core/message.service';

/** Average rating per manufacturer from the rating list. Ratings whose car has no manufacturer are skipped. */
export function averageByManufacturer(ratings: Rating[]): ManufacturerRating[] {
  const totals = new Map<string, { sum: number; count: number }>();
  for (const rating of ratings) {
    const name = rating.car.manufacturer?.name;
    if (!name) {
      continue;
    }
    const total = totals.get(name) ?? { sum: 0, count: 0 };
    total.sum += rating.rating;
    total.count++;
    totals.set(name, total);
  }
  return [...totals].map(([manufacturer, { sum, count }]) => ({ manufacturer, rating: sum / count }));
}

@Component({
  selector: 'app-report',
  standalone: true,
  templateUrl: './report.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ReportComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly averages = signal<ManufacturerRating[]>([]);

  /**
   * Reads the report from GET /api/manufacturers/ratings, the endpoint the GWT app uses. That endpoint
   * answers HTTP 500 whenever a car has lost its manufacturer (deleting a manufacturer does that), so
   * if it fails the same averages are computed from GET /api/ratings instead of showing an empty report.
   */
  ngOnInit(): void {
    this.api.getAverageRatings().pipe(
      catchError(() => this.api.getRatings().pipe(map(averageByManufacturer))),
    ).subscribe({
      next: (list) => this.averages.set(list),
      error: () => this.messages.error('The report could not be loaded.'),
    });
  }
}
