/* Success and error messages (GWT MessageWidget). */
.messages {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 200;
  pointer-events: none;
}

.message {
  pointer-events: auto;
  display: flex;
  justify-content: space-between;
